/**
 * Unit tests for LevenbergMarquardtOptimizer.doOptimize().
 * Since doOptimize is protected, we use a Testable subclass to expose it.
 */
public class LevenbergMarquardtOptimizer_doOptimize_TriageGen2Test {

    private TestableLevenbergMarquardtOptimizer optimizer;
    private JacobianFunction mockFunction;
    private Target mockTarget;

    // Subclass to access protected method and inject mocks
    private static class TestableLevenbergMarquardtOptimizer extends LevenbergMarquardtOptimizer {
        private final JacobianFunction function;
        private final Target target;
        private final RealMatrix weightMatrix;

        public TestableLevenbergMarquardtOptimizer(JacobianFunction function, Target target, RealMatrix weightMatrix) {
            this.function = function;
            this.target = target;
            this.weightMatrix = weightMatrix;
        }

        @Override
        protected Target getTarget() { return target; }

        @Override
        protected JacobianFunction getFunction() { return function; }

        @Override
        protected RealMatrix getWeightSquareRoot() { return weightMatrix; }

        @Override
        protected double[] getStartPoint() { return new double[]{1.0}; }

        @Override
        protected PointVectorValuePair doOptimize() {
            try {
                Method method = super.getClass().getSuperclass().getDeclaredMethod("doOptimize");
                method.setAccessible(true);
                return (PointVectorValuePair) method.invoke(this);
            } catch (Exception e) {
                if (e.getCause() instanceof ConvergenceException) {
                    throw (ConvergenceException) e.getCause();
                }
                throw new RuntimeException(e);
            }
        }
    }

    @Before
    public void setUp() {
        mockFunction = mock(JacobianFunction.class);
        mockTarget = mock(Target.class);
        when(mockTarget.length).thenReturn(2);
        optimizer = new TestableLevenbergMarquardtOptimizer(mockFunction, mockTarget, new Array2DRowRealMatrix(new double[][]{{1, 0}, {0, 1}}));
    }

    @Test
    public void testDoOptimize_SimpleConvergence() {
        // Setup a simple linear problem: f(x) = x, target = 0
        // Residual = x - 0. Jacobian = 1.
        double[] startPoint = {1.0};
        when(mockFunction.value(any(double[].class))).thenReturn(new double[]{1.0});
        when(mockFunction.jacobian(any(double[].class))).thenReturn(new Array2DRowRealMatrix(new double[][]{{1.0}}));

        // We need to mock the internal behavior by providing a concrete implementation via the optimizer's logic
        // Since we cannot easily mock the protected 'computeObjectiveValue' etc. without a full mock,
        // we rely on the fact that the optimizer uses getFunction().value()

        // For the sake of this test, we assume the optimizer calls getFunction().value() and getFunction().jacobian()
        // Note: In real Commons Math, these are protected methods that call the function.

        // This test is a skeleton. In a real professional setting, one would use 
        // a specialized Mockito spy or a more robust Testable class to override computeObjectiveValue.
    }

    @Test
    public void testDoOptimize_ConvergenceReachedImmediately() {
        // Mocking a scenario where maxCosine <= orthoTolerance
        // This requires the Jacobian to be orthogonal to the residual.

        // Let's use a simplified approach: trigger the orthogonality condition.
        // If currentCost is 0, maxCosine remains 0.

        // Create a subclass that forces the desired values
        TestableLevenbergMarquardtOptimizer fastOptimizer = new TestableLevenbergMarquardtOptimizer(mockFunction, mockTarget, new Array2DRowRealMatrix(new double[][]{{1, 0}, {0, 1}})) {
            @Override
            protected double[] computeObjectiveValue(double[] point) { return new double[]{0.0, 0.0}; }
            @Override
            protected double[] computeResiduals(double[] objective) { return new double[]{0.0, 0.0}; }
            @Override
            protected double computeCost(double[] residuals) { return 0.0; }
            @Override
            protected void checkParameters() {}
            @Override
            protected ConvergenceChecker<PointVectorValuePair> getConvergenceChecker() { return null; }
        };

        PointVectorValuePair result = fastOptimizer.doOptimize();
        assertNotNull(result);
        assertEquals(0.0, fastOptimizer.getCost(), 1e-10);
    }

    @Test(expected = ConvergenceException.class)
    public void testDoOptimize_TooSmallOrthogonalityTolerance() {
        // Force maxCosine to be extremely small but non-zero to trigger the machine epsilon check
        // This is hard to trigger without precise control over the Jacobian and Residuals.
        // We simulate it by providing a very small residual and a very large Jacobian.

        TestableLevenbergMarquardtOptimizer errorOptimizer = new TestableLevenbergMarquardtOptimizer(mockFunction, mockTarget, new Array2DRowRealMatrix(new double[][]{{1, 0}, {0, 1}})) {
            @Override
            protected double[] computeObjectiveValue(double[] point) { return new double[]{1e-20, 1e-20}; }
            @Override
            protected double[] computeResiduals(double[] objective) { return new double[]{1e-20, 1e-20}; }
            @Override
            protected double computeCost(double[] residuals) { return 1e-20; }
            @Override
            protected void checkParameters() {}
            @Override
            protected double getOrthoTolerance() { return 1e-10; }
            // Force the loop to hit the exception via the maxCosine check
            @Override
            protected void qrDecomposition(RealMatrix jacobian) {
                // Mocked QR behavior to ensure maxCosine is calculated
            }
        };

        // In a real environment, we would use a concrete implementation of the function
        // that produces the specific mathematical conditions required to hit the branches.
        errorOptimizer.doOptimize();
    }

    @Test
    public void testDoOptimize_ConvergenceWithChecker() {
        ConvergenceChecker<PointVectorValuePair> checker = mock(ConvergenceChecker.class);
        when(checker.converged(anyInt(), any(), any())).thenReturn(true);

        TestableLevenbergMarquardtOptimizer checkerOptimizer = new TestableLevenbergMarquardtOptimizer(mockFunction, mockTarget, new Array2DRowRealMatrix(new double[][]{{1, 0}, {0, 1}})) {
            @Override
            protected double[] computeObjectiveValue(double[] point) { return new double[]{1.0, 1.0}; }
            @Override
            protected double[] computeResiduals(double[] objective) { return new double[]{1.0, 1.0}; }
            @Override
            protected double computeCost(double[] residuals) { return 1.0; }
            @Override
            protected void checkParameters() {}
            @Override
            protected ConvergenceChecker<PointVectorValuePair> getConvergenceChecker() { return checker; }
        };

        PointVectorValuePair result = checkerOptimizer.doOptimize();
        assertNotNull(result);
    }
}
